sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var INCIDENT_TRANSFORM_MAP_SYS_ID = '9b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4e';

	try {
		var body = request.body.data;

		if (!body || !body.short_description || !body.x_xurre_imr_incident
				|| !body.urgency_sys_id || !body.state_sys_id || !body.entity_type_sys_id || !body.mandatory_fields) {
			response.setStatus(400);
			return {
				status: "error",
				message: "Missing required fields: short_description, x_xurre_imr_incident, urgency_sys_id, state_sys_id, entity_type_sys_id, mandatory_fields"
			};
		}

		var importGR = new GlideRecord('x_xurre_imr_u_import_incident');
		importGR.initialize();
		importGR.setValue('operation', 'create_incident');
		importGR.setValue('short_description', body.short_description);
		importGR.setValue('description', body.description || '');
		importGR.setValue('urgency_sys_id', body.urgency_sys_id);
		importGR.setValue('state_sys_id', body.state_sys_id);
		importGR.setValue('snow_priority_sys_id', body.snow_priority_sys_id || '');
		importGR.setValue('x_xurre_imr_incident', body.x_xurre_imr_incident);
		importGR.setValue('entity_type_sys_id', body.entity_type_sys_id);
		importGR.setValue('entity_type_mapping_mode', body.entity_type_mapping_mode || 0);
		importGR.setValue('entity_record_sys_id', body.entity_record_sys_id || '');
		importGR.setValue('service_name', body.service_name || '');
		importGR.setValue('mandatory_fields', JSON.stringify(body.mandatory_fields));
		var importSysId = importGR.insert();

		new GlideImportSetTransformerWorker(importSysId, INCIDENT_TRANSFORM_MAP_SYS_ID).start(false);

		importGR.get(importSysId);
		var resultStatus = importGR.getValue('result_status');
		var resultMessage = importGR.getValue('result_message');
		var resultSysId = importGR.getValue('result_sys_id');
		var resultNumber = importGR.getValue('result_number');

		if (resultStatus !== 'success') {
			response.setStatus(400);
			return { status: "error", message: resultMessage };
		}

		gs.info("Incident created successfully");
		response.setStatus(201);
		return {
			status: "success",
			message: "Incident created",
			sys_id: resultSysId,
			number: resultNumber
		};

	} catch (err) {
		gs.error("Incident creation failed: " + err.message);
		response.setStatus(400);
		return { status: "error", message: err.message };
	}

})(request, response);
